function contains(sol,x){switch(sol.type){case'all':return true;case'none':return false;case'ray':return holds(x,sol.rel,sol.k);case'interval':return holds(sol.lo,sol.loRel,x)&&holds(x,sol.hiRel,sol.hi);case'point':return x.eq(sol.k);default:return false;}}
