function describeSolution(sol){switch(sol.type){case'ray':return{type:'ray',rel:sol.rel,boundary:sol.k.toText()};case'interval':return{type:'interval',lo:sol.lo.toText(),loRel:sol.loRel,hi:sol.hi.toText(),hiRel:sol.hiRel};case'point':return{type:'point',value:sol.k.toText()};default:return{type:sol.type};}}
