const ASK_NAME={mean:['\\bar{x}','mean'],median:['\\text{median}','median'],range:['\\text{range}','range'],min:['\\min','min'],max:['\\max','max'],q1:['Q_1','Q1'],q3:['Q_3','Q3'],iqr:['\\text{IQR}','IQR'],mad:['\\text{MAD}','MAD'],'sd-population':['\\sigma',LSIGMA],'sd-sample':['s','s'],'variance-population':['\\sigma^2',LSIGMA+SQ],'variance-sample':['s^2','s'+SQ],count:['n','n'],sum:['\\sum x',SIGMA+'x'],};const LABEL={mean:'The mean',median:'The median',range:'The range',min:'The minimum',max:'The maximum',q1:'Q1',q3:'Q3',iqr:'The IQR',mad:'The mean absolute deviation','sd-population':'The population standard deviation','sd-sample':'The sample standard deviation','variance-population':'The population variance','variance-sample':'The sample variance',count:'The count',sum:'The sum',};function askQuantity(ask,A){const need=A.need;switch(ask){case'count':return Q(new Frac(A.S.n));case'sum':return Q(need('sum'));case'mean':return Q(need('mean'));case'median':return Q(need('median'));case'min':return Q(A.S.min);case'max':return Q(A.S.max);case'range':return Q(need('range'));case'q1':return Q(need('q1'));case'q3':return Q(need('q3'));case'iqr':return Q(need('iqr'));case'mad':return Q(need('mad'));case'variance-population':return need('varP');case'variance-sample':return need('varS');case'sd-population':return need('sdP');case'sd-sample':return need('sdS');default:return null;}}
